import {validGuestEmail} from './invitation-email.js';
export function cleanGuests(value){return Array.isArray(value)?value.slice(0,100).filter(guest=>guest&&typeof guest.name==='string'&&guest.name.trim()).map(guest=>({id:typeof guest.id==='string'?guest.id.slice(0,50):crypto.randomUUID(),name:guest.name.trim().slice(0,80),email:validGuestEmail(guest.email)?String(guest.email).trim():'',allowedCount:Math.max(1,Math.min(10,Math.floor(Number(guest.allowedCount)||1))),status:['accepted','declined'].includes(guest.status)?guest.status:'invited',attendingCount:Math.max(0,Math.min(10,Math.floor(Number(guest.attendingCount)||0)))})):[];}
export function initGuests({getState,onChange,onPreview,onDownload,onEmail,toast}){
 const panel=document.createElement('details');panel.className='guest-manager options-panel';panel.innerHTML='<summary>Quem vai celebrar com vocês? <span class="guest-count"></span></summary><p class="guest-local">Baixe um convite individual, envie o arquivo e importe a confirmação recebida em “Respostas que chegaram”. Sua lista fica neste aparelho.</p><p class="email-local-note">Você pode baixar um rascunho de e-mail com o convite anexado e enviá-lo pelo seu programa de e-mail. Para enviar um link individual pelo Capimimo, publique o convite e abra a lista em Conferir e entregar. O endereço fica nesta lista local; confira e informe-o novamente antes do envio.</p><div class="guest-add"><div class="field"><label for="guest-name">Nome no convite</label><input id="guest-name" maxlength="80" placeholder="Ex.: Família Silva"></div><div class="field"><label for="guest-email">E-mail do convidado (opcional)</label><input id="guest-email" type="email" maxlength="254" placeholder="nome@exemplo.com"></div><div class="field"><label for="guest-party">Pessoas no convite</label><select id="guest-party"></select></div><button class="add-guest" type="button">Adicionar à lista</button></div><details class="bulk-guests"><summary>Adicionar vários nomes de uma vez</summary><label for="bulk-guest-names">Um convidado por linha. Opcional: nome; e-mail</label><textarea id="bulk-guest-names" rows="4" maxlength="8100" placeholder="Ana e João\nFamília Silva\nDona Lúcia"></textarea><button class="add-bulk-guests" type="button">Adicionar nomes</button><p class="bulk-guest-status" role="status"></p></details><div class="guest-stats" role="status"></div><div class="guest-list"></div><p class="guest-empty">Sua lista começa com alguém especial. Adicione o primeiro nome acima.</p>';
 document.querySelector('#invite-fields').after(panel);const $=s=>panel.querySelector(s);for(let count=1;count<=10;count++)$('#guest-party').add(new Option(String(count),String(count)));
 function add(names,count=1){const guests=cleanGuests(getState().guests),known=new Set(guests.map(guest=>guest.name.toLocaleLowerCase('pt-BR')));let added=0;for(const raw of names){const [rawName,rawEmail]=raw.split(';'),name=rawName.trim(),email=(rawEmail||'').trim();if(!name||name.length>80||known.has(name.toLocaleLowerCase('pt-BR')))continue;if(guests.length>=100)break;guests.push({id:crypto.randomUUID(),name,email:validGuestEmail(email)?email:'',allowedCount:count,status:'invited',attendingCount:0});known.add(name.toLocaleLowerCase('pt-BR'));added++;}onChange({guests});toast(added?added+(added===1?' convite na sua lista.':' convites na sua lista.'):'Confira os nomes. Há um limite de 100 convites, sem nomes repetidos.');return added;}
 $('.add-guest').addEventListener('click',()=>{if(!$('#guest-name').value.trim()){$('#guest-name').focus();toast('Escreva um nome para o convite.');return;}if($('#guest-email').value&&!validGuestEmail($('#guest-email').value)){toast('Confira o e-mail antes de adicionar.');$('#guest-email').focus();return;}if(add([$('#guest-name').value+';'+$('#guest-email').value],Number($('#guest-party').value))){$('#guest-name').value='';$('#guest-email').value='';}});
 $('.add-bulk-guests').addEventListener('click',()=>{const input=$('#bulk-guest-names'),guests=cleanGuests(getState().guests),known=new Set(guests.map(guest=>guest.name.toLocaleLowerCase('pt-BR'))),accepted=[],remaining=[],reasons=new Set();for(const raw of input.value.split(/\r?\n/)){if(!raw.trim())continue;const parts=raw.split(';'),name=parts[0].trim(),email=(parts[1]||'').trim();let reason='';if(!name||name.length>80)reason='Confira os nomes: use de 1 a 80 caracteres.';else if(parts.length>2||email&&!validGuestEmail(email))reason='Confira os e-mails e use nome; e-mail em cada linha.';else if(known.has(name.toLocaleLowerCase('pt-BR')))reason='Há nomes repetidos na lista.';else if(guests.length+accepted.length>=100)reason='O limite é de 100 convites. Remova um convite da lista para adicionar outros.';if(reason){remaining.push(raw);reasons.add(reason);continue;}accepted.push(raw);known.add(name.toLocaleLowerCase('pt-BR'));}if(accepted.length)add(accepted);input.value=remaining.join('\n');const message=(accepted.length?accepted.length+(accepted.length===1?' convite adicionado. ':' convites adicionados. '):'Nenhum convite adicionado. ')+(remaining.length?'As linhas que precisam de revisão continuam no campo. '+[...reasons].join(' '):'');$('.bulk-guest-status').textContent=message;toast(message);if(remaining.length)input.focus();});
 const rows=new Map(),composerBuffers=new Map();let renderedDraft;const composerKey=state=>typeof state.draftId==='string'&&state.draftId?state.draftId:state;const composerFields=['guest-name','guest-email','guest-party','bulk-guest-names'];
 function render(){
  const state=getState();panel.hidden=state.format!=='convite';const guests=cleanGuests(state.guests),list=$('.guest-list');
  const context=composerKey(state);if(renderedDraft!==context){if(renderedDraft!==undefined)composerBuffers.set(renderedDraft,{fields:composerFields.map(id=>$('#'+id).value),status:$('.bulk-guest-status').textContent});const saved=composerBuffers.get(context);composerFields.forEach((id,index)=>$('#'+id).value=saved?.fields[index]??(id==='guest-party'?'1':''));$('.bulk-guest-status').textContent=saved?.status||'';list.replaceChildren();rows.clear();renderedDraft=context;}
  $('.guest-count').textContent=guests.length+'/100';$('.guest-empty').hidden=!!guests.length;$('.add-guest').disabled=guests.length>=100;$('.add-bulk-guests').disabled=guests.length>=100;
  const accepted=guests.filter(guest=>guest.status==='accepted'),declined=guests.filter(guest=>guest.status==='declined');$('.guest-stats').textContent=guests.length?accepted.reduce((total,guest)=>total+guest.attendingCount,0)+' presenças · '+(guests.length-accepted.length-declined.length)+' respostas pendentes · lista local':'';
  const ids=new Set(guests.map(guest=>guest.id));for(const [id,row] of rows)if(!ids.has(id)){row.element.remove();rows.delete(id);}
  for(const guest of guests){
   let row=rows.get(guest.id);
   if(!row){
    const draftContext=context,id=guest.id,element=document.createElement('article');element.className='guest-row';
    const current=()=>composerKey(getState())===draftContext?cleanGuests(getState().guests).find(item=>item.id===id):null;
    const copy=document.createElement('div'),name=document.createElement('strong'),status=document.createElement('span'),emailInput=document.createElement('input');emailInput.type='email';emailInput.className='guest-email-edit';emailInput.placeholder='E-mail (opcional)';emailInput.maxLength=254;
    const button=(text,className='')=>{const item=document.createElement('button');item.type='button';item.textContent=text;item.className=className;return item;};
    const preview=button('Ver convite'),download=button('Baixar convite','download-guest-invitation'),emailButton=button('Preparar e-mail','guest-email-draft'),remove=button('×','guest-remove');
    row={element,name,status,emailInput,preview,download,emailButton,remove,email:'',busy:false};const entry=row;
    const validate=()=>{const email=emailInput.value.trim(),valid=!email||validGuestEmail(email);emailInput.setCustomValidity(valid?'':'Confira o endereço de e-mail.');emailInput.setAttribute('aria-invalid',String(!valid));emailButton.disabled=entry.busy||!email||!valid;return valid;};
    const saveEmail=()=>{if(!validate())return null;const latest=current();if(!latest)return null;const email=emailInput.value.trim();if(latest.email!==email){onChange({guests:cleanGuests(getState().guests).map(item=>item.id===id?{...item,email}:item)});}return {...latest,email};};
    emailInput.addEventListener('input',validate);emailInput.addEventListener('change',()=>{if(!saveEmail()&&!validate())toast('Confira o endereço de e-mail.');});
    preview.addEventListener('click',()=>{const latest=current();if(latest)onPreview(latest);});
    remove.addEventListener('click',()=>{if(!current())return;onChange({guests:cleanGuests(getState().guests).filter(item=>item.id!==id)});});
    download.addEventListener('click',async()=>{const latest=current();if(!latest)return;download.disabled=true;try{if(await onDownload(latest)===true)toast('Convite de '+latest.name+' baixado.');}catch{toast('Não foi possível preparar o convite agora.');}finally{download.disabled=false;}});
    emailButton.addEventListener('click',async()=>{const latest=saveEmail();if(!latest?.email){emailInput.reportValidity();return;}if(entry.busy)return;entry.busy=true;validate();try{if(await onEmail(latest)===true)toast('Rascunho com convite anexado baixado. Abra no seu programa de e-mail, confira e envie.');}catch(error){toast(error.message||'Não foi possível preparar o e-mail.');}finally{entry.busy=false;validate();}});
    copy.append(name,status,emailInput);element.append(copy,preview,download,emailButton,remove);rows.set(id,row);list.append(element);row.validate=validate;
   }
   row.name.textContent=guest.name;row.status.textContent=guest.status==='accepted'?guest.attendingCount+' '+(guest.attendingCount===1?'presença':'presenças')+' confirmada'+(guest.attendingCount===1?'':'s')+' neste aparelho':guest.status==='declined'?'Não poderá ir · resposta importada':'Até '+guest.allowedCount+' '+(guest.allowedCount===1?'pessoa':'pessoas')+' · sem resposta';
   if(row.email!==guest.email||!row.initialized){row.emailInput.value=guest.email||'';row.email=guest.email;row.initialized=true;}
   row.preview.setAttribute('aria-label','Ver convite de '+guest.name);row.download.setAttribute('aria-label','Baixar convite de '+guest.name);row.remove.setAttribute('aria-label','Remover '+guest.name+' da lista');row.emailInput.setAttribute('aria-label','E-mail de '+guest.name);row.emailButton.setAttribute('aria-label','Preparar e-mail para '+guest.name);row.validate();
  }
 }

 render();return {render,reply({id,status,count}){const guests=cleanGuests(getState().guests),guest=guests.find(item=>item.id===id);if(!guest||!['accepted','declined'].includes(status)||!Number.isInteger(count)||count<0||count>guest.allowedCount||(status==='accepted'&&count<1))return false;guest.status=status;guest.attendingCount=status==='declined'?0:count;onChange({guests});return true;}};
}
